"use strict";

/**
 * Pure parse/render for Cloudflare's published edge ranges.
 *
 * infra/cloudflare/ips-v4.txt and ips-v6.txt are the single source of truth
 * for "which addresses are Cloudflare". Two things are derived from them:
 *
 *   - infra/nginx/cloudflare-realip.conf, generated by renderRealipConf below
 *     (scripts/cloudflare-ips.js writes it; `--check` fails when it is stale);
 *   - the host firewall, which infra/firewall/cloudflare-only.sh builds from
 *     ips-v4.txt at apply time.
 *
 * The files keep Cloudflare's own format — one CIDR per line, nothing else —
 * so a refresh is a verbatim copy of https://www.cloudflare.com/ips-v4 and
 * /ips-v6, and a drift check is a plain set comparison.
 *
 * Kept apart from the CLI so jest can require it without argv, network or
 * process.exit. Requiring this file has no side effects.
 */
const net = require("net");

const MIN_PREFIX = { 4: 8, 6: 16 };
const MAX_PREFIX = { 4: 32, 6: 128 };

/**
 * One CIDR per line; blank lines ignored. Anything else throws — a malformed
 * list must never reach nginx or the firewall, where the failure it produced
 * would be a rejected Cloudflare edge (outage) or a trusted spoofed header.
 */
function parseRanges(text, family) {
  if (family !== 4 && family !== 6) {
    throw new Error(`family must be 4 or 6, got ${family}`);
  }
  const ranges = [];
  const lines = String(text).split("\n");
  lines.forEach((raw, i) => {
    const line = raw.trim();
    if (!line) return;
    const m = line.match(/^([^/\s]+)\/(\d{1,3})$/);
    if (!m) throw new Error(`line ${i + 1}: not a CIDR: ${JSON.stringify(line)}`);
    const [, addr, bitsText] = m;
    if (net.isIP(addr) !== family) {
      throw new Error(`line ${i + 1}: not an IPv${family} address: ${JSON.stringify(line)}`);
    }
    const bits = Number(bitsText);
    // A /0 (or anything close) is never a Cloudflare range; it is a typo that
    // would trust every client's CF-Connecting-IP and open the firewall.
    if (bits < MIN_PREFIX[family] || bits > MAX_PREFIX[family]) {
      throw new Error(`line ${i + 1}: prefix /${bits} out of range: ${JSON.stringify(line)}`);
    }
    if (ranges.includes(line)) throw new Error(`line ${i + 1}: duplicate range ${line}`);
    ranges.push(line);
  });
  if (ranges.length === 0) throw new Error(`no IPv${family} ranges`);
  return ranges;
}

/** The nginx snippet. Order follows the source files, v4 first. */
function renderRealipConf(v4, v6) {
  return [
    "# GENERATED by scripts/cloudflare-ips.js from infra/cloudflare/ips-v4.txt",
    "# and ips-v6.txt. Do not edit: change the lists and run",
    "# `npm run cloudflare-ips`. `npm test` fails while this file is stale.",
    "#",
    "# Installed by .github/workflows/deploy.yml as",
    "# /etc/nginx/snippets/skkuverse-cloudflare-realip.conf and included at http",
    "# level by infra/nginx/api.skkuverse.com, so every vhost on the host logs",
    "# and forwards the real client. CF-Connecting-IP is trusted only from these",
    "# ranges; a header sent by anyone else is ignored.",
    ...v4.map((r) => `set_real_ip_from ${r};`),
    ...v6.map((r) => `set_real_ip_from ${r};`),
    "real_ip_header CF-Connecting-IP;",
    "",
  ].join("\n");
}

/** Set difference both ways; order-insensitive, like Cloudflare's own list. */
function diffRanges(expected, actual) {
  return {
    missing: actual.filter((r) => !expected.includes(r)),
    extra: expected.filter((r) => !actual.includes(r)),
  };
}

module.exports = { parseRanges, renderRealipConf, diffRanges };
